  Future<void> _save(BuildContext context,WidgetRef ref,Map<String,dynamic> patch) async { try { final saved=await ref.read(adminRepositoryProvider).upsertTreatment(patch); ref.invalidate(adminTreatmentsProvider); if(context.mounted)context.go(AppRoutes.adminTreatmentEdit(saved)); } on PostgrestException catch(e) { if(context.mounted)_message(context,_rpcMessage(context,e.message)); } }
